('abre-tu-negocio-online', 'Abre tu negocio online', 'Del primer producto a las primeras ventas: elige qué vender, monta tu tienda y consigue tus primeros clientes.', 'Marisol Vega', 'Negocios', 14900, 'USD', 'ai', 'https://hgpkfeqxzewwypgodrjq.supabase.co/storage/v1/object/public/trailers/fd9af8d4-7a0e-4379-88e0-7ffcdc01aab0/abre-tu-negocio-online.mp4', 14, '{"lines":["Abre tu","negocio","online"],"hl":1,"prop":"doc","bust":"long","outfit":"#2b3f66","glow":"#ffb547","a":"#12304a","b":"#5a2340","glyph":"$"}'::jsonb, array['¿Y si tu primera venta fuera esta semana?', 'Elige qué vender. Monta tu tienda.', 'Seis módulos. Tres plantillas. Cero rodeos.', '“Abrí mi tienda un martes y vendí el jueves.” — Ana, alumna', 'Abre tu negocio online desde cero.']::text[], 2140, 4.9, true, true),
('ingles-para-cerrar-ventas', 'Inglés para cerrar ventas', 'Frases, guiones y roleplays para vender en inglés sin perder tu acento ni tu confianza.', 'Coach Andrés R.', 'Idiomas', 7900, 'USD', 'creator', 'https://hgpkfeqxzewwypgodrjq.supabase.co/storage/v1/object/public/trailers/fd9af8d4-7a0e-4379-88e0-7ffcdc01aab0/ingles-para-cerrar-ventas.mp4', 14, '{"lines":["Inglés para","cerrar","ventas"],"hl":2,"prop":"bubble","bust":"short","outfit":"#1f4d52","glow":"#7fd6c8","a":"#0f3d3e","b":"#1b2a5a","glyph":"En"}'::jsonb, array['Tu inglés te está costando ventas.', 'Frases reales para cerrar el trato.', 'Roleplays con feedback.', '“Cerré mi primer cliente en inglés.” — Carlos, alumno', 'Inglés para cerrar ventas.']::text[], 5320, 4.8, true, true),
('barberia-pro', 'Barbería pro', 'Degradados, barba y atención al cliente. Incluye cómo cobrar y llenar tu agenda.', 'Luis ''El Fino''', 'Oficios', 19900, 'USD', 'creator', 'https://hgpkfeqxzewwypgodrjq.supabase.co/storage/v1/object/public/trailers/fd9af8d4-7a0e-4379-88e0-7ffcdc01aab0/barberia-pro.mp4', 14, '{"lines":["Barbería","pro"],"hl":1,"prop":"scissors","bust":"beard","outfit":"#4a2424","glow":"#ff8a5c","a":"#3a1c1c","b":"#1c1c3a","glyph":"BP"}'::jsonb, array['Un buen degradado no se improvisa.', 'Técnica, barba y atención al cliente.', 'Y cómo llenar tu agenda.', '“Pasé de 5 a 25 clientes por semana.” — Luis, alumno', 'Barbería profesional desde cero.']::text[], 980, 4.9, true, true),
