('tu-primera-propiedad-de-inversion', 'Tu primera propiedad de inversión', 'Financiamiento, análisis de zonas y cómo evitar los errores caros.', 'Jorge Alcántara', 'Inversión', 24900, 'USD', 'creator', 'https://hgpkfeqxzewwypgodrjq.supabase.co/storage/v1/object/public/trailers/fd9af8d4-7a0e-4379-88e0-7ffcdc01aab0/tu-primera-propiedad-de-inversion.mp4', 14, '{"lines":["Tu primera","propiedad"],"hl":1,"prop":"house","bust":"short","outfit":"#1f4a3a","glow":"#6fd38b","a":"#173a2d","b":"#0d2a45","glyph":"RE"}'::jsonb, array['Tu primera propiedad no es un sueño lejano.', 'Financiamiento y análisis de zonas.', 'Los errores caros, explicados.', '“Compré mi primer departamento a los 29.” — Jorge, alumno', 'Tu primera propiedad de inversión.']::text[], 1560, 4.8, true, true),
