('ingles-para-la-entrevista-de-trabajo', 'Inglés para la entrevista de trabajo', 'Preguntas reales, respuestas modelo y práctica con feedback.', 'Prof. Valeria Cruz', 'Idiomas', 4900, 'USD', 'creator', 'https://hgpkfeqxzewwypgodrjq.supabase.co/storage/v1/object/public/trailers/fd9af8d4-7a0e-4379-88e0-7ffcdc01aab0/ingles-para-la-entrevista-de-trabajo.mp4', 14, '{"lines":["Inglés para","la entrevista"],"hl":1,"prop":"case","bust":"long","outfit":"#3f3a5a","glow":"#ffcf7a","a":"#2a3a4a","b":"#4a3a2a","glyph":"Hi"}'::jsonb, array['La entrevista decide tu empleo.', 'Preguntas reales y respuestas modelo.', 'Práctica con feedback.', '“Me contrataron a la primera.” — Valeria, alumna', 'Inglés para la entrevista de trabajo.']::text[], 7340, 4.8, true, true)
